   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.fn_ca_financial_alert_to_incident() TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_ca_financial_alert_to_incident()'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.fn_ca_financial_alert_to_incident()', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.fn_ca_finding_key(p_dedupe_key text, p_classification text, p_layer text, p_club_id uuid, p_union_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  k text := COALESCE(p_dedupe_key, '');
  before text;
BEGIN
  FOR i IN 1..4 LOOP
    before := k;
    k := regexp_replace(k, ':[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$', '');
    k := regexp_replace(k, ':[0-9a-fA-F]{32}$', '');
    k := regexp_replace(k, ':[0-9]{4}-[0-9]{2}-[0-9]{2}(-[0-9]{2})?$', '');
    EXIT WHEN k = before;
  END LOOP;

  IF k = '' THEN
    k := COALESCE(p_classification, 'unknown');
  END IF;

  RETURN k
      || '|' || COALESCE(p_layer, 'unknown')
      || '|' || COALESCE(p_club_id::text, '-')
      || '|' || COALESCE(p_union_id::text, '-');
END $function$;
