CREATE OR REPLACE FUNCTION public.fn_ca_is_midway_scope(p_union_id uuid DEFAULT NULL::uuid, p_club_id uuid DEFAULT NULL::uuid, p_table_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    -- THE FOUR ESTATES (Dan, 2026-09-03): Midway Union with Club JAQK and
    -- SHARK CLUB inside it, and Deep Stack Society standing alone. Until
    -- chip standard Phase 4.3 (2026-09-04) this scope was Midway only, so an
    -- incident about Deep Stack Society's money - its jackpot reserve running
    -- dry, a payout that could not reconcile - was dropped before it was
    -- filed. Deep Stack is an estate; its incidents file.
    -- platform-substrate incidents: no entity dimension anywhere = global
    -- checks (supply, suspense, guards, crons, diamonds) that protect every
    -- union including Midway. These always file.
    (p_union_id IS NULL AND p_club_id IS NULL AND p_table_id IS NULL
     AND p_tournament_id IS NULL
     AND COALESCE(p_metadata->>'union_id','') = ''
     AND COALESCE(p_metadata->>'club_id','') = '')
    OR p_union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    OR p_club_id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id = p_club_id
         AND c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.union_clubs uc
       WHERE uc.club_id = p_club_id
         AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
    )
    OR EXISTS (
      SELECT 1 FROM public.tables t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_table_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR EXISTS (
      SELECT 1 FROM public.tournaments t
      JOIN public.clubs c ON c.id = t.club_id
       WHERE t.id = p_tournament_id
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )
    OR COALESCE(p_metadata->>'union_id', '') = 'fade0000-0000-0000-0000-000000000001'
    OR EXISTS (
      SELECT 1 FROM public.clubs c
       WHERE c.id::text = COALESCE(p_metadata->>'club_id', '')
         AND (
           c.id IN ('fade0000-0000-0000-0000-000000000001'::uuid, '2a1132b9-5ba2-42e6-9f01-30a7fcffebe3'::uuid)
           OR c.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           OR EXISTS (
             SELECT 1 FROM public.union_clubs uc
              WHERE uc.club_id = c.id
                AND uc.union_id = 'fade0000-0000-0000-0000-000000000001'::uuid
           )
         )
    )), false);
$function$;
ALTER FUNCTION public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb) OWNER TO "postgres";
-- Exact ACL FUNCTION: public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)'; END IF;
 new_acl := '{postgres=X/postgres,service_role=X/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', 'public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('f',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', 'public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', 'public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb) FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb) TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.fn_ca_is_midway_scope(uuid,uuid,uuid,uuid,jsonb)', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.fn_ca_issuance_leg_is_registered()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_outside text[] := public.fn_ca_noncirculating_chip_stores();
  v_pol public.ca_mint_policy%ROWTYPE;
  v_24h numeric;
BEGIN
  IF NEW.from_type = ANY (v_outside) AND NOT (NEW.to_type = ANY (v_outside))
     AND NEW.category <> 'correction' THEN
    SELECT * INTO v_pol FROM public.ca_mint_policy WHERE id = 1;
    IF NEW.amount > v_pol.per_operation_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: % chips in one leg is over the per-operation ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        NEW.amount, v_pol.per_operation_cap_chips USING ERRCODE = 'P0403';
    END IF;
    v_24h := public.fn_ca_mint_issued_24h('chips', NEW.id) + NEW.amount;
    IF v_24h > v_pol.rolling_24h_cap_chips THEN
      RAISE EXCEPTION 'issuance refused: this leg would bring the last 24 hours to % chips, over the rolling ceiling of % (ca_mint_policy; raise it with a reason through fn_ca_mint_policy_set before a deliberate batch)',
        v_24h, v_pol.rolling_24h_cap_chips USING ERRCODE = 'P0403';
    END IF;
  END IF;
  PERFORM public.fn_ca_register_issuance_leg(NEW.id);
  RETURN NULL;
END;
$function$;
