CREATE OR REPLACE FUNCTION public.fn_emit_club_union_access_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_recipient uuid;
  v_union uuid;
  v_side text;
BEGIN
  IF NEW.owner_id IS DISTINCT FROM OLD.owner_id THEN
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, OLD.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'before'));
    PERFORM public.fn_emit_game_management_event(
      'management_access_changed', NEW.id, NEW.union_id, NEW.owner_id,
      'club', NEW.id, NULL,
      jsonb_build_object('operation', 'owner_changed', 'side', 'after'));
  END IF;

  IF NEW.union_id IS DISTINCT FROM OLD.union_id THEN
    FOR v_union, v_side IN
      SELECT OLD.union_id, 'before' WHERE OLD.union_id IS NOT NULL
      UNION ALL
      SELECT NEW.union_id, 'after' WHERE NEW.union_id IS NOT NULL
    LOOP
      FOR v_recipient IN
        SELECT OLD.owner_id
        UNION SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
        UNION SELECT u.owner_id FROM public.unions u WHERE u.id = v_union
        UNION SELECT a.user_id FROM public.union_admins a WHERE a.union_id = v_union
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, v_union, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', v_side));
      END LOOP;
    END LOOP;

    -- Leaving a union has a new standalone scope. Its operators still need an
    -- authoritative refresh even though there is no new union recipient set.
    IF NEW.union_id IS NULL THEN
      FOR v_recipient IN
        SELECT NEW.owner_id
        UNION SELECT m.user_id FROM public.club_members m
          WHERE m.club_id = NEW.id
            AND m.role IN ('owner','co_owner','admin')
            AND m.status IN ('active','approved')
            AND COALESCE(m.is_active, true)
      LOOP
        PERFORM public.fn_emit_game_management_event(
          'management_access_changed', NEW.id, NULL, v_recipient,
          'club', NEW.id, NULL,
          jsonb_build_object('operation', 'union_changed', 'side', 'after'));
      END LOOP;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
ALTER FUNCTION public.fn_emit_club_union_access_event() OWNER TO "postgres";
-- Exact ACL FUNCTION: public.fn_emit_club_union_access_event()
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_emit_club_union_access_event()'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.fn_emit_club_union_access_event()'; END IF;
 new_acl := '{postgres=X/postgres,service_role=X/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', 'public.fn_emit_club_union_access_event()';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('f',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', 'public.fn_emit_club_union_access_event()';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', 'public.fn_emit_club_union_access_event()';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION public.fn_emit_club_union_access_event() FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.fn_emit_club_union_access_event() TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_emit_club_union_access_event()'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.fn_emit_club_union_access_event()', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.fn_emit_game_management_event(p_event_type text, p_club_id uuid DEFAULT NULL::uuid, p_union_id uuid DEFAULT NULL::uuid, p_recipient_id uuid DEFAULT NULL::uuid, p_entity_type text DEFAULT NULL::text, p_entity_id uuid DEFAULT NULL::uuid, p_command_id uuid DEFAULT NULL::uuid, p_payload jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_scope_kind text; v_scope_id uuid; v_union_id uuid;
BEGIN
  IF p_union_id IS NOT NULL THEN
    v_scope_kind := 'union'; v_scope_id := p_union_id; v_union_id := p_union_id;
  ELSIF p_club_id IS NOT NULL THEN
    SELECT s.scope_kind,s.scope_id,s.union_id
      INTO v_scope_kind,v_scope_id,v_union_id
      FROM public.fn_game_management_scope(p_club_id) s;
  END IF;
  INSERT INTO public.game_management_events(
    event_type,scope_kind,scope_id,club_id,union_id,recipient_id,
    entity_type,entity_id,command_id,actor_id,payload
  ) VALUES (
    p_event_type,v_scope_kind,v_scope_id,p_club_id,v_union_id,p_recipient_id,
    p_entity_type,p_entity_id,p_command_id,auth.uid(),COALESCE(p_payload,'{}'::jsonb)
  );
END;
$function$;
