CREATE OR REPLACE FUNCTION public.fn_is_unsafe_url(p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_host text;
BEGIN
    -- NULL / empty → safe (means no image set)
    IF p_url IS NULL OR length(btrim(p_url)) = 0 THEN
        RETURN false;
    END IF;

    -- 2 KiB cap to keep logs/queries sane
    IF length(p_url) > 2048 THEN
        RETURN true;
    END IF;

    -- Reject NULs + control chars (incl. \r \n \t \b etc)
    IF p_url ~ '[\x00-\x1F\x7F]' THEN
        RETURN true;
    END IF;

    -- Protocol-relative //host/... is ambiguous outside HTML and not needed.
    -- Reject before the relative-path check below.
    IF p_url ~ '^//' THEN
        RETURN true;
    END IF;

    -- Relative absolute path (e.g. "/smarter-poker-logo.png") is SAFE.
    -- Cannot cause SSRF (not a fetchable URL) and resolves same-origin in <img>.
    IF p_url ~ '^/[^/]' THEN
        RETURN false;
    END IF;

    -- Require http:// or https:// explicitly
    IF NOT (p_url ~* '^https?://') THEN
        RETURN true;
    END IF;

    -- Extract hostname; strip userinfo (user:pass@) if present
    v_host := lower(regexp_replace(p_url, '^https?://(?:[^@/]+@)?([^/?#:]+).*$', '\1', 'i'));

    -- localhost + no-dot hostnames (covers 'localhost', 'admin', 'intranet', etc.)
    IF v_host = 'localhost' OR v_host NOT LIKE '%.%' THEN
        RETURN true;
    END IF;

    -- IPv4 private / reserved ranges
    IF v_host ~ '^(127\.|10\.|0\.|169\.254\.|192\.168\.)' THEN
        RETURN true;
    END IF;
    IF v_host ~ '^172\.(1[6-9]|2[0-9]|3[0-1])\.' THEN
        RETURN true;
    END IF;

    -- IPv6 loopback / unique-local / link-local
    IF v_host ~ '^\[?(::1|::|fc[0-9a-f]{2}:|fd[0-9a-f]{2}:|fe[89ab][0-9a-f]:)' THEN
        RETURN true;
    END IF;

    -- Clean
    RETURN false;
END;
$function$;
ALTER FUNCTION public.fn_is_unsafe_url(text) OWNER TO "postgres";
-- Exact ACL FUNCTION: public.fn_is_unsafe_url(text)
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_is_unsafe_url(text)'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.fn_is_unsafe_url(text)'; END IF;
 new_acl := '{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', 'public.fn_is_unsafe_url(text)';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('f',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', 'public.fn_is_unsafe_url(text)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', 'public.fn_is_unsafe_url(text)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION public.fn_is_unsafe_url(text) FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.fn_is_unsafe_url(text) TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_is_unsafe_url(text)'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.fn_is_unsafe_url(text)', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.fn_log_seat_stack_exit()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_stack numeric;
  v_kind  text;
BEGIN
  IF EXISTS(SELECT 1 FROM public.tables t JOIN public.clubs c ON c.id=t.club_id
            WHERE t.id=OLD.table_id AND c.asset='diamonds') THEN
    RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
  END IF;
  IF TG_OP = 'DELETE' THEN
    -- A departed seat being tidied up is not an exit: its stack left when
    -- left_at was stamped, and that is already recorded below.
    IF OLD.left_at IS NOT NULL THEN RETURN OLD; END IF;
    v_stack := COALESCE(OLD.stack, 0);
    v_kind  := 'deleted';
  ELSE
    IF OLD.left_at IS NOT NULL OR NEW.left_at IS NULL THEN RETURN NEW; END IF;
    v_stack := COALESCE(OLD.stack, 0);
    v_kind  := 'left';
  END IF;

  IF v_stack <= 0 THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  -- CASH ONLY. A tournament stack is play money inside the event -- it credits
  -- no wallet when the seat ends, so it cannot be lost in the sense this table
  -- exists to detect. Filtering HERE rather than in the report keeps ~2,000
  -- meaningless rows an hour out of the audit trail entirely.
  IF EXISTS (SELECT 1 FROM public.tables t
              WHERE t.id = OLD.table_id AND t.tournament_id IS NOT NULL) THEN
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  INSERT INTO public.ca_seat_stack_exits
    (seat_id, table_id, user_id, club_id, seat_number, stack, exit_kind, db_role, app_name)
  VALUES (OLD.id, OLD.table_id, OLD.user_id, OLD.club_id, OLD.seat_number,
          v_stack, v_kind, current_user,
          NULLIF(current_setting('application_name', true), ''));

  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$function$;
