 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.fn_protect_profile_username_and_gate()'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.fn_protect_profile_username_and_gate()'; END IF;
 new_acl := '{postgres=X/postgres,service_role=X/postgres}'::aclitem[];
