CREATE OR REPLACE FUNCTION public.fn_seat_insert_cancel_waitlist()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  UPDATE public.table_waitlist
     SET status = 'seated'
   WHERE table_id = NEW.table_id
     AND user_id  = NEW.user_id
     AND status IN ('waiting', 'notified');
