CREATE OR REPLACE FUNCTION public.is_reserved_username(p_username text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v text;
  v_exact text[] := ARRAY[
    -- System / admin
    'admin','administrator','root','sudo','superuser','system','sys','default',
    'staff','owner','mod','moderator','manager','team','official','officials',
    'verified','certified','authentic','authorized','employee','employees',
    'founder','ceo','cto','cfo','coo','exec','executive',
    -- Support / contact
    'support','helpdesk','helpcenter','helpcentre','help','helpme','helpus',
    'contact','contactus','contact_us','info','inquiry','hello','hi',
    'customerservice','customer_service','customersupport','customer_support',
    'cs','csr','faq','feedback','report','abuse',
    -- Brand: Smarter.Poker
    'smarter','smarterpoker','smartpoker','smarter_poker','smarter.poker',
    'smarter_pkr','smarterpkr','smarter_official','smarterofficial',
    'smarter_support','smarter_team','smarter_admin','smarter_help',
    'smarter_staff','smarter_mod','smarterpoker_official','smarterpoker_team',
    'smarterpoker_support','smarterpoker_admin','smarterpoker_help',
    'sp_official','sp_support','sp_admin','sp_team',
    -- Sub-products
    'jarvis','geeves','pokerbrain','poker_brain','clubarena','club_arena',
    'clubcommander','club_commander','clubcomm','pokernearme','poker_near_me',
    -- Founder / known accounts
    'kingfish','danbekavac','dan_bekavac','dan.bekavac','bekavac','dbekavac',
    -- Generic AI / bots
    'bot','robot','ai','gpt','chatgpt','claude','openai','anthropic',
    -- Web / dev infra
    'api','apis','www','web','app','apps','mobile','http','https','ftp',
    'dev','prod','staging','localhost','test','testing','demo','example',
    'sample','samples',
    -- Auth / security
    'password','passwd','login','signup','signin','signout','logout',
    'register','security','auth','authentication','oauth','sso','session',
    'token','mfa','2fa','otp','verify','verification',
    -- Communication
    'email','mail','postmaster','webmaster','hostmaster','noreply','no_reply',
    'mailer','mailerdaemon','newsletter',
    -- Money / finance
    'money','cash','bank','banking','wallet','treasury','payment','payments',
    'billing','invoice','stripe','paypal','venmo','cashapp','zelle','square',
    'applepay','googlepay','plaid',
    -- Poker terms
    'poker','dealer','tournament','tournaments','cashier','casino','casinos',
    'vip','vips','premium','pro','pros','gold','silver','platinum',
    'diamond','diamonds','chip','chips','table','tables','lobby',
    -- Competitor / impersonation
    'pokerstars','ggpoker','partypoker','888poker','americascardroom','acr',
    'wsop','worldseries','pokerbros','clubgg','pokerrrr','suprema','pokerdom',
    'naturalpoker','x-poker','xpoker',
    -- Scam / spam
    'free','freemoney','free_money','winner','winners','prize','jackpot',
    'lottery','claim','claimnow','claim_now','urgent','alert','warning',
    'notice','security_alert','account_locked','password_reset','verify_now',
    -- Generic placeholders
    'null','undefined','nil','none','void','anonymous','anon','guest','user',
    'users','everyone','all','nobody','somebody','default','me','you','i',
    -- Edge cases
    'dot','period','underscore','hyphen','space','tab'
  ];
BEGIN
  v := lower(trim(both ' @' from coalesce(p_username, '')));
  IF v IS NULL OR v = '' THEN RETURN true; END IF;

  -- Exact-match
  IF v = ANY(v_exact) THEN RETURN true; END IF;

  -- Prefix patterns - brand impersonation
  IF v ~ '^smarter[._]'      THEN RETURN true; END IF;  -- smarter_X, smarter.X
  IF v ~ '^smarterpoker'     THEN RETURN true; END IF;  -- anything starting with smarterpoker
  IF v ~ '^smartpoker'       THEN RETURN true; END IF;
  IF v ~ '^smarterpkr'       THEN RETURN true; END IF;
  IF v ~ '^jarvis[._0-9]'    THEN RETURN true; END IF;
  IF v ~ '^geeves[._0-9]'    THEN RETURN true; END IF;
  IF v ~ '^kingfish'         THEN RETURN true; END IF;  -- kingfish*, no impersonation of Dan
  IF v ~ '^bekavac'          THEN RETURN true; END IF;
  IF v ~ '^danbekavac'       THEN RETURN true; END IF;
  IF v ~ '^pokerbrain'       THEN RETURN true; END IF;
  IF v ~ '^clubarena'        THEN RETURN true; END IF;
  IF v ~ '^clubcommander'    THEN RETURN true; END IF;

  -- Prefix patterns - system role impersonation (must have separator to avoid blocking 'admins'-as-substring etc)
  IF v ~ '^admin[._]'        THEN RETURN true; END IF;
  IF v ~ '^support[._]'      THEN RETURN true; END IF;
  IF v ~ '^staff[._]'        THEN RETURN true; END IF;
  IF v ~ '^official[._]'     THEN RETURN true; END IF;
  IF v ~ '^moderator[._]'    THEN RETURN true; END IF;
  IF v ~ '^help[._]'         THEN RETURN true; END IF;

  -- Suffix patterns - system role impersonation
  IF v ~ '_admin$'           THEN RETURN true; END IF;
  IF v ~ '_support$'         THEN RETURN true; END IF;
  IF v ~ '_staff$'           THEN RETURN true; END IF;
  IF v ~ '_official$'        THEN RETURN true; END IF;
  IF v ~ '_team$'            THEN RETURN true; END IF;
  IF v ~ '_mod$'             THEN RETURN true; END IF;
  IF v ~ '_moderator$'       THEN RETURN true; END IF;
  IF v ~ '_help$'            THEN RETURN true; END IF;

  RETURN false;
END;
$function$;
ALTER FUNCTION public.is_reserved_username(text) OWNER TO "postgres";
-- Exact ACL FUNCTION: public.is_reserved_username(text)
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.is_reserved_username(text)'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.is_reserved_username(text)'; END IF;
 new_acl := '{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', 'public.is_reserved_username(text)';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('f',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', 'public.is_reserved_username(text)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', 'public.is_reserved_username(text)';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION public.is_reserved_username(text) FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.is_reserved_username(text) TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.is_reserved_username(text)'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.is_reserved_username(text)', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.lock_club_cashier_hierarchy_mutation()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_old_club uuid := case when tg_op in ('UPDATE','DELETE') then old.club_id else null end;
  v_new_club uuid := case when tg_op in ('INSERT','UPDATE') then new.club_id else null end;
begin
  if v_old_club is not null and (v_new_club is null or v_old_club::text <= v_new_club::text) then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  if v_new_club is not null and v_new_club is distinct from v_old_club then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_new_club::text,0));
  end if;
  if v_old_club is not null and v_new_club is not null and v_old_club::text > v_new_club::text then
    perform pg_advisory_xact_lock(hashtextextended('cashier-hierarchy:'||v_old_club::text,0));
  end if;
  return case when tg_op='DELETE' then old else new end;
end
$function$;
