   EXECUTE 'REVOKE ALL ON FUNCTION public.trg_tournament_completed_stats() FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
