 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.trg_tournament_completed_stats()'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.trg_tournament_completed_stats()', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.trg_tournament_pool_finalization_window_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_late_level_cap integer := COALESCE(NULLIF(NEW.late_reg_levels, 0),
                                       NULLIF(NEW.rebuy_levels, 0), 0);
  v_rebuy_level_cap integer := COALESCE(NULLIF(NEW.rebuy_levels, 0),
                                        NULLIF(NEW.late_reg_levels, 0), 0);
  v_current_level integer := COALESCE(NEW.current_level, 0);
  /* An unexpired future window is just as binding as one whose start clock has
     arrived. Finalizing it early would publish an add-on promise that the
     finalized-pool trigger later has to refuse. */
  v_addon_open boolean := COALESCE(NEW.add_on_available, false)
                          AND NEW.addon_period_ends_at IS NOT NULL
                          AND clock_timestamp() < NEW.addon_period_ends_at;
BEGIN
  IF COALESCE(OLD.prize_pool_finalized, false)
     AND NOT COALESCE(NEW.prize_pool_finalized, false) THEN
    RAISE EXCEPTION
      'finalized tournament % prize pool cannot be reopened', NEW.id
      USING ERRCODE = 'check_violation';
  END IF;
  IF NOT COALESCE(NEW.prize_pool_finalized, false)
     OR COALESCE(OLD.prize_pool_finalized, false) THEN
    RETURN NEW;
  END IF;

  IF NEW.status IN ('ANNOUNCED', 'REGISTERING')
     AND (v_late_level_cap > 0 OR COALESCE(NEW.late_reg_mins, 0) > 0
          OR COALESCE(NEW.is_rebuy, false) OR COALESCE(NEW.is_reentry, false)
          OR COALESCE(NEW.add_on_available, false)) THEN
    RAISE EXCEPTION
      'tournament % cannot finalize its prize pool before its post-start entry windows open', NEW.id
      USING ERRCODE = 'check_violation';
  END IF;

  IF NEW.status = 'RUNNING' THEN
    IF v_late_level_cap > 0 AND v_current_level < v_late_level_cap THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool before late registration level % closes',
        NEW.id, v_late_level_cap USING ERRCODE = 'check_violation';
    END IF;
    IF v_late_level_cap <= 0 AND COALESCE(NEW.late_reg_mins, 0) > 0
       AND (NEW.started_at IS NULL OR clock_timestamp()
            < NEW.started_at + make_interval(mins => NEW.late_reg_mins)) THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool while timed late registration is open', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF (COALESCE(NEW.is_rebuy, false) OR COALESCE(NEW.is_reentry, false))
       AND v_rebuy_level_cap <= 0 AND COALESCE(NEW.late_reg_mins, 0) <= 0 THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool while an uncapped rebuy or re-entry offer is open', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF (COALESCE(NEW.is_rebuy, false) OR COALESCE(NEW.is_reentry, false))
       AND v_rebuy_level_cap > 0 AND v_current_level < v_rebuy_level_cap THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool before rebuy level % closes',
        NEW.id, v_rebuy_level_cap USING ERRCODE = 'check_violation';
    END IF;
    IF v_addon_open THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool before its promised add-on window closes', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
    IF COALESCE(NEW.add_on_available, false)
       AND (NEW.addon_period_started_at IS NULL OR NEW.addon_period_ends_at IS NULL) THEN
      RAISE EXCEPTION
        'tournament % cannot finalize its prize pool before its add-on window is durably bounded', NEW.id
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;
ALTER FUNCTION public.trg_tournament_pool_finalization_window_guard() OWNER TO "postgres";
-- Exact ACL FUNCTION: public.trg_tournament_pool_finalization_window_guard()
DO $acl$
DECLARE a record; role_name text; own oid; old_acl aclitem[]; new_acl aclitem[];
        work_old aclitem[]; actual_acl aclitem[];
BEGIN
 IF current_user <> 'postgres' OR NOT EXISTS
    (SELECT FROM pg_catalog.pg_roles WHERE rolname=current_user AND rolsuper) THEN
  RAISE EXCEPTION 'ACL installation requires the owned fixture postgres superuser';
 END IF;
 SELECT proowner, proacl INTO own, old_acl FROM pg_catalog.pg_proc WHERE oid='public.trg_tournament_pool_finalization_window_guard()'::regprocedure;
 IF NOT FOUND THEN RAISE EXCEPTION 'Missing ACL target: %', 'public.trg_tournament_pool_finalization_window_guard()'; END IF;
 new_acl := '{postgres=X/postgres,service_role=X/postgres}'::aclitem[];
 -- Exact no-op retains catalog NULL and original entry ordering.
 IF old_acl::text IS NOT DISTINCT FROM new_acl::text THEN RETURN; END IF;
 
 IF new_acl IS NULL THEN
  RAISE EXCEPTION 'Captured object ACL is NULL/default but archive ACL differs: %', 'public.trg_tournament_pool_finalization_window_guard()';
 END IF;

 work_old := COALESCE(old_acl,pg_catalog.acldefault('f',own));
 -- SQL '{}' arrays have zero dimensions. Never pass one (or NULL) to aclexplode.
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  IF pg_catalog.array_ndims(work_old) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(work_old) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Unreviewed old ACL shape/grantor graph: %', 'public.trg_tournament_pool_finalization_window_guard()';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  IF pg_catalog.array_ndims(new_acl) <> 1 OR EXISTS
     (SELECT FROM pg_catalog.aclexplode(new_acl) WHERE grantor<>own) THEN
   RAISE EXCEPTION 'Captured ACL requires an unreviewed grantor graph: %', 'public.trg_tournament_pool_finalization_window_guard()';
  END IF;
 END IF;
 IF COALESCE(pg_catalog.cardinality(work_old),0)>0 THEN
  FOR a IN SELECT DISTINCT grantee FROM pg_catalog.aclexplode(work_old) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   EXECUTE 'REVOKE ALL ON FUNCTION public.trg_tournament_pool_finalization_window_guard() FROM '||role_name||' RESTRICT';
  END LOOP;
 END IF;
 IF COALESCE(pg_catalog.cardinality(new_acl),0)>0 THEN
  FOR a IN SELECT * FROM pg_catalog.aclexplode(new_acl) LOOP
   role_name:=CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.quote_ident(pg_catalog.pg_get_userbyid(a.grantee)) END;
   -- PostgreSQL superuser GRANT records the actual owner, matching every
   -- captured grantor; retain each privilege's explicit grant-option bit.
   EXECUTE 'GRANT '||a.privilege_type||' ON FUNCTION public.trg_tournament_pool_finalization_window_guard() TO '||role_name||
     CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END;
  END LOOP;
 END IF;
 SELECT proowner, proacl INTO own, actual_acl FROM pg_catalog.pg_proc WHERE oid='public.trg_tournament_pool_finalization_window_guard()'::regprocedure;
 IF actual_acl::text IS DISTINCT FROM new_acl::text THEN
  RAISE EXCEPTION 'Exact ACL catalog shape/order/privileges differ: % expected %, actual %',
    'public.trg_tournament_pool_finalization_window_guard()', new_acl::text, actual_acl::text;
 END IF;
END $acl$;
CREATE OR REPLACE FUNCTION public.trg_tournament_table_close_requires_empty()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_parent_status text;
BEGIN
  IF NEW.tournament_id IS NULL
     OR NOT (
       (lower(NEW.status::text) = 'closed'
        AND lower(OLD.status::text) IS DISTINCT FROM 'closed')
       OR (COALESCE(NEW.is_deleted, false) AND NOT COALESCE(OLD.is_deleted, false))
     ) THEN
    RETURN NEW;
  END IF;

  SELECT upper(t.status::text)
    INTO v_parent_status
    FROM public.tournaments t
   WHERE t.id = NEW.tournament_id;

  /* Terminal cleanup has its own atomic settlement/seat-release contracts.
     The dangerous path is a joinable or playing event whose table is being
     removed underneath a field that may still acquire a seat. */
  IF v_parent_status IN ('REGISTERING', 'RUNNING')
     AND EXISTS (
       SELECT 1
         FROM public.table_seats s
        WHERE s.table_id = OLD.id
          AND s.left_at IS NULL
     ) THEN
    RAISE EXCEPTION
      'TOURNAMENT_TABLE_CLOSE_NOT_EMPTY: table % still has a live seat', OLD.id
      USING ERRCODE = '23514';
  END IF;

  IF lower(NEW.status::text) = 'closed' THEN
    NEW.current_players := 0;
  END IF;
  RETURN NEW;
END;
$function$;
